<script>
// --- Simulated page-detail lookup (prototype only) -------------------------
// In the real app this comes from the actual page. Here we fake it so the
// client can experience the "details fill themselves in" behaviour.
const CANNED = {
  "example.com": { title:"Example Domain", desc:"This domain is for use in illustrative examples in documents." },
};
function fakeLookup(url){
  let host="";
  try { host = new URL(url).hostname.replace(/^www\./,''); } catch(e){ return null; }
  const known = CANNED[host];
  const site = host;
  const nameGuess = host.split('.')[0].replace(/(^|\W)\w/g, c=>c.toUpperCase());
  return {
    title: known ? known.title : (nameGuess + " — page title"),
    site: site,
    desc: known ? known.desc : "A short description pulled from the page would appear here.",
    letter: (host[0]||'?').toUpperCase()
  };
}

const urlEl=document.getElementById('url');
const fetching=document.getElementById('fetching');
const preview=document.getElementById('preview');
const saveBtn=document.getElementById('save');
let current=null, tags=[];
let timer=null;

urlEl.addEventListener('input', ()=>{
  clearTimeout(timer);
  const val=urlEl.value.trim();
  preview.classList.add('hidden');
  current=null; refreshSave();
  if(!val){ fetching.classList.add('hidden'); return; }
  fetching.classList.remove('hidden');
  timer=setTimeout(()=>{
    const data=fakeLookup(val);
    fetching.classList.add('hidden');
    if(!data) return;
    current=data;
    document.getElementById('p-title').textContent=data.title;
    document.getElementById('p-site').textContent=data.site;
    document.getElementById('p-desc').textContent=data.desc;
    document.getElementById('fav').textContent=data.letter;
    preview.classList.remove('hidden');
    refreshSave();
  }, 700); // simulate a brief network lookup
});

// --- Tags ------------------------------------------------------------------
const tagEntry=document.getElementById('tag-entry');
const tagsInput=document.getElementById('tags-input');
tagEntry.addEventListener('keydown', e=>{
  if(e.key==='Enter' && tagEntry.value.trim()){
    e.preventDefault();
    const t=tagEntry.value.trim();
    if(!tags.includes(t)){ tags.push(t); renderTags(); }
    tagEntry.value='';
  } else if(e.key==='Backspace' && !tagEntry.value && tags.length){
    tags.pop(); renderTags();
  }
});
function renderTags(){
  [...tagsInput.querySelectorAll('.chip')].forEach(c=>c.remove());
  tags.forEach((t,i)=>{
    const chip=document.createElement('span');
    chip.className='chip';
    chip.innerHTML=`${t} <button aria-label="remove">×</button>`;
    chip.querySelector('button').onclick=()=>{ tags.splice(i,1); renderTags(); };
    tagsInput.insertBefore(chip, tagEntry);
  });
}

function refreshSave(){ saveBtn.disabled = !current; }

// --- Save ------------------------------------------------------------------
const list=document.getElementById('list');
const saved=[];
saveBtn.addEventListener('click', ()=>{
  if(!current) return;
  saved.unshift({ ...current, tags:[...tags], note:document.getElementById('note').value.trim(), url:urlEl.value.trim() });
  renderList();
  // reset the form
  urlEl.value=''; document.getElementById('note').value=''; tags=[]; renderTags();
  preview.classList.add('hidden'); current=null; refreshSave();
});
function renderList(){
  if(!saved.length){ list.innerHTML='<div class="empty">Nothing saved yet.</div>'; return; }
  list.innerHTML='';
  saved.forEach(b=>{
    const el=document.createElement('div');
    el.className='list-item';
    const tagsHtml=b.tags.map(t=>`<span class="chip">${t}</span>`).join('');
    el.innerHTML=`
      <div class="fav">${b.letter}</div>
      <div style="flex:1">
        <div class="title"><a href="${b.url}" target="_blank" rel="noopener">${b.title}</a></div>
        <div class="site">${b.site}</div>
        ${b.note?`<div class="note">${b.note}</div>`:''}
        <div class="meta">${tagsHtml}</div>
      </div>`;
    list.appendChild(el);
  });
}
document.body.setAttribute('data-harness-ready','true');
</script>
